def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1

    marker = min(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == marker]
    min_r = min(r for r, c in points)
    min_c = min(c for r, c in points)
    shape = [(r - min_r, c - min_c) for r, c in points]
    shape_h = max(r for r, c in shape) + 1
    shape_w = max(c for r, c in shape) + 1

    out = [row[:] for row in grid]
    for top in range(h - shape_h + 1):
        for left in range(w - shape_w + 1):
            if all(grid[top + r][left + c] == 0 for r, c in shape):
                for r, c in shape:
                    out[top + r][left + c] = marker
    return out
